using System.Text;
using System.Text.Json;
internal static class LibraryNobQuantityTests {
 internal static async Task Run(){
  var root=Path.Combine(Path.GetTempPath(),"LibraryNob-"+Guid.NewGuid().ToString("N"));var header=new SimAssemblyHeader("01PART                ","fixture","V1.2","PART                ","PART","A","202020","A",false);var key=header.SourceKeyRaw;
  var store=new SimLibraryBomStore(root,()=>[header]);var actor=new SimPersona("fixture","fixture","Fixture","ACTIVE",[],[],true,"fixture");
  void Check(bool test,string name){if(!test)throw new Exception(name);}async Task Reject(Func<Task> f){try{await f();}catch(SimRfqIntakeProblem){return;}throw new Exception("Expected quantity rejection");}
  string Export(string qty=".0001",string divisor="10",string unit="",string find="NOB",string description="PRE-CUT",string factor="1",string scrap="0")=>string.Join('\t',SimVproParser.Headers)+"\tDRAW#=PART REV A\n"+string.Join('\t',new[]{"001","MPN",description,"",divisor,qty,unit,factor,scrap,"0","0","P",""})+"\n"+string.Join('\t',new[]{"002","","("+find+") J2","","0","0","","0","0","0","0","",""})+"\n";
  string Encode(string s)=>Convert.ToBase64String(Encoding.ASCII.GetBytes(s));
  var v=await store.Get(key,actor);v=await store.Change(new(key,v.Token,"START"),actor);var prior=Export("1","1","EA","1","ORDINARY");v=await store.Change(new(key,v.Token,"IMPORT",FileName:"old.txt",TextBase64:Encode(prior)),actor);var old=JsonSerializer.Serialize(v.Record.Draft,SimLibraryBomStore.Json);
  var source=Export();v=await store.Change(new(key,v.Token,"UPDATE_SOURCE",FileName:"new.txt",TextBase64:Encode(source)),actor);var row=v.Record.Draft!.Rows.Single();
  Check(row.Quantity=="0"&&row.Unit==""&&!row.Dnp,"suppressed NOB zero, no invented UOM or DNP");Check(SimLibraryBomStore.OptionalNobDemand(row)==0,"zero required demand");Check(row.Source!.Extracted["sourceQuantityRaw"]==".0001"&&row.Source.Extracted["sourceDivisorRaw"]=="10"&&row.Source.Extracted["sourceUnitRaw"]=="","raw factors retained");Check(v.Record.Draft.Import!.VproImport.RawRows[0][5]==".0001","literal TXT values preserved");Check(v.Record.Draft.Import.VproImport.SourceNotes!.Any(n=>n.Kind=="OPTIONAL_NOB_SUPPRESSION"),"explicit mapping note");Check(v.Record.Draft.Rows.All(r=>r.Acceptance is null&&!r.IdentityConfirmed),"not autoapproved");Check(JsonSerializer.Serialize(v.Record.SourceVersions!.Single().Snapshot,SimLibraryBomStore.Json)==old,"source history preserved");Check((await store.Evidence(key,null,actor)).SequenceEqual(Encoding.ASCII.GetBytes(source)),"literal new evidence");
  var edit=new LibraryRowEdit(row.Id,row.Find,row.SourcePartNumber,row.Description,"0","",row.ReferenceDesignators,"MFG","MPN","",true,false,"",false);
  v=await store.Change(new(key,v.Token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:[edit],RowId:row.Id),actor);Check(v.Record.Draft!.Rows[0].Acceptance is not null,"zero NOB blank source unit accepted after explicit identity review");
  var token=v.Token;await Reject(async()=>await store.Change(new(key,token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:[edit with{Quantity="2"}],RowId:row.Id),actor));Check((await store.Get(key,actor)).Token==token,"positive missing unit failure atomic");
  v=await store.Change(new(key,v.Token,"SAVE",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:[edit with{Quantity="2",Unit="EA"}]),actor);Check(v.Record.Draft!.Rows[0].Acceptance is null,"positive material edit invalidates row acceptance");Check(SimLibraryBomStore.OptionalNobDemand(v.Record.Draft.Rows[0])==2,"positive quantity not suppressed");
  v=await store.Change(new(key,v.Token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:[edit with{Quantity="2",Unit="EA"}],RowId:row.Id),actor);var reopened=await new SimLibraryBomStore(root,()=>[header]).Get(key,actor);Check(reopened.Token==v.Token&&reopened.Record.Draft!.Rows[0].Quantity=="2","positive demand survives reopen");
  foreach(var q in new[]{"","-1","1000001","bad"})Check(SimLibraryBomStore.Blockers(v.Record.Draft! with{Rows=[v.Record.Draft!.Rows[0] with{Quantity=q}]}).Any(b=>b.Contains("quantity")),"invalid NOB quantity");
  var blank=SimVproParser.Parse(Encoding.ASCII.GetBytes(Export("0","1")),"fixture","PART","A","Fixture",libraryOptionalNob:true);Check(blank.Rows[0].Values["quantity"]=="0","explicit zero source");var positive=SimVproParser.Parse(Encoding.ASCII.GetBytes(Export("3","1","EA")),"fixture","PART","A","Fixture",libraryOptionalNob:true);Check(positive.Rows[0].Values["quantity"]=="3","explicit positive source");
  foreach(var bad in new[]{Export(".0001","10","EA","1"),Export("0","1","EA","1"),Export("2","10","EA"),Export("1","1",""),Export(factor:".0001"),Export(scrap:"1")})await Reject(()=>{SimVproParser.Parse(Encoding.ASCII.GetBytes(bad),"fixture","PART","A","Fixture",libraryOptionalNob:true);return Task.CompletedTask;});
  await Reject(()=>{SimVproParser.Parse(Encoding.ASCII.GetBytes(source),"fixture","PART","A","Fixture");return Task.CompletedTask;}); // Job parser behavior deliberately unchanged.
  var ordinary=row with{Find="1",Quantity="0",Unit="EA"};Check(SimLibraryBomStore.Blockers(v.Record.Draft! with{Rows=[ordinary]}).Any(b=>b.Contains("positive quantity")),"ordinary zero still rejected");
  var multi=Export()+string.Join('\n',Export().Split('\n').Skip(1)).Replace("001\tMPN","003\tMPN").Replace("002\t\t","004\t\t");var parsed=SimVproParser.Parse(Encoding.ASCII.GetBytes(multi),"fixture","PART","A","Fixture",libraryOptionalNob:true);Check(parsed.Rows.Length==2&&parsed.Rows.Select(r=>r.RowId).Distinct().Count()==2&&parsed.Rows.All(r=>r.Values["quantity"]=="0"),"distinct repeated zero NOB");
  var cut=Export("1","1","EA","18","STOCK").Replace("(18) J2","(18) J2,3 - CUT TO SIZE")+string.Join('\n',Export().Split('\n').Skip(1)).Replace("001\tMPN","003\tMPN").Replace("002\t\t","004\t\t");v=await store.Change(new(key,v.Token,"UPDATE_SOURCE",FileName:"cut.txt",TextBase64:Encode(cut)),actor);Check(SimLibraryBomStore.SourceInstructionApplies(v.Record.Draft!,v.Record.Draft!.Rows[0])&&!SimLibraryBomStore.PreparationApplies(v.Record.Draft!,v.Record.Draft!.Rows[1]),"stock source note independent of optional NOB");Check(SimLibraryBomStore.Blockers(v.Record.Draft with{Rows=[v.Record.Draft.Rows[0] with{PreparationRequired=true},v.Record.Draft.Rows[1]]}).Any(b=>b.Contains("Preparation details pending")),"explicit material preparation remains blocked");
  Console.WriteLine("PASS Library optional NOB: exact legacy suppression -> zero, raw evidence/history, explicit zero/positive, honest UOM, reload/acceptance invalidation, failure atomicity, duplicate NOB, ordinary/job regressions and independent stock preparation guard.");
 }
}
